<?php
require_once '../config/auth.php'; require_once '../config/database.php';
if (($_SESSION['staff_role'] ?? '') !== 'master') { http_response_code(403); exit('Acesso restrito ao Staff Master.'); }
$search=trim((string)($_GET['q']??''));$category=trim((string)($_GET['category']??''));$action=trim((string)($_GET['action']??''));$staffId=(int)($_GET['staff_id']??0);$userId=(int)($_GET['user_id']??0);$start=trim((string)($_GET['start']??''));$end=trim((string)($_GET['end']??''));$where=[];$params=[];if($search!==''){ $where[]='(a.affected_user_name LIKE ? OR a.staff_name LIKE ? OR a.details LIKE ? OR a.action LIKE ?)';$t='%'.$search.'%';array_push($params,$t,$t,$t,$t);}if($category!==''){$where[]='a.category=?';$params[]=$category;}if($action!==''){$where[]='a.action=?';$params[]=$action;}if($staffId>0){$where[]='a.staff_id=?';$params[]=$staffId;}if($userId>0){$where[]='a.affected_user_id=?';$params[]=$userId;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$start)){$where[]='a.created_at>=?';$params[]=$start.' 00:00:00';}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$end)){$where[]='a.created_at<=?';$params[]=$end.' 23:59:59';}$w=$where?'WHERE '.implode(' AND ',$where):'';$q=$pdo->prepare("SELECT * FROM audit_logs a $w ORDER BY a.created_at DESC,a.id DESC LIMIT 5000");$q->execute($params);$rows=$q->fetchAll();function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Relatório de Auditoria - Morningfall Creators</title><style>@page{size:A4 landscape;margin:10mm}body{font-family:Arial,sans-serif;color:#111;font-size:9px;margin:0}.head{border-bottom:2px solid #111;padding-bottom:10px;margin-bottom:12px}.head h1{margin:0 0 4px;font-size:20px}.muted{color:#555}table{width:100%;border-collapse:collapse}th,td{border:1px solid #aaa;padding:5px;vertical-align:top}th{background:#eee}pre{white-space:pre-wrap;margin:0;font:8px Arial}.actions{position:fixed;right:10px;top:10px}button{padding:8px 12px}@media print{.actions{display:none}}</style></head><body><div class="actions"><button onclick="window.print()">🖨️ Salvar/Imprimir PDF</button></div><div class="head"><h1>Morningfall Creators — Relatório de Auditoria</h1><div>Gerado em <?=e(date('d/m/Y H:i:s'))?> · <?=count($rows)?> registros</div><div class="muted">Filtros: <?=e(($start?:'início').' até '.($end?:'fim'))?><?= $search?' · Busca: '.e($search):''?></div></div><table><thead><tr><th>Data/Hora</th><th>Staff</th><th>Usuário afetado</th><th>Ação</th><th>Categoria</th><th>Alteração</th><th>Antes</th><th>Depois</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('d/m/Y H:i:s',strtotime($r['created_at'])))?></td><td><?=e($r['staff_name'])?></td><td><?=e($r['affected_user_name']??'—')?></td><td><?=e($r['action'])?></td><td><?=e($r['category'])?></td><td><?=e($r['details']??'')?></td><td><pre><?=e($r['before_data']??'—')?></pre></td><td><pre><?=e($r['after_data']??'—')?></pre></td></tr><?php endforeach;?></tbody></table><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),300));</script></body></html>
